        : `Run ${numericId}: not verified — ${res.reason || "evidence missing or mismatched"}. It cannot be approved.`,
      res.verified === true ? "info" : "warn",
    );
  } catch (err) {
    showToast?.(`Run ${numericId}: verification failed — ${String(err?.message || err)}`, "warn");
  }
}

